using System; // Reject invalid sensory state at the saved-world boundary.
using System.IO; // Compare independently recorded prior-release behavior.
using Outbreak.Contracts; // Keep heard source knowledge separate from human target memory.
using Outbreak.Core; // Execute actual event propagation and navigation.
using Outbreak.Persistence; // Verify complete deterministic save continuation.
public static partial class Program // Extend the real-code acceptance suite.
{ // Begin zombie sound acceptance.
    private static void CheckZombieSoundCases() // Verify hearing, priority, blocked sources and bounded persistence.
    { // Begin controlled investigation cases.
        Check("An idle zombie follows actual impacts and acquires the human only after sight opens", () => // Do not turn hearing into omniscient pursuit or arbitrary door attacks.
        { // Begin the listener's complete approach.
            World world = EncounterScenarios.ZombieSoundInvestigation(); Run(world, 2); ActorState listener = world.ActorAt(2); Require(listener.heardDoorX == 3 && listener.heardDoorY == 2 && listener.heardDoorUntilTick == 27 && listener.targetId == 0 && listener.stress == 0, "Impact did not create zombie sound knowledge independently of human knowledge."); Require(world.ActorAt(1).heardDoorUntilTick == 0, "Attacker heard its own strike."); Run(world, 1); Require(world.ActorAt(2).x == 6 && world.ActorAt(2).targetId == 0, "Listener did not approach its heard source."); Run(world, 15); Require(world.ActorAt(2).x == 4 && world.ActorAt(2).targetId == 0 && world.DoorHealthAt(3, 2) == 36, "Sound-only listener crossed or damaged the closed door."); Run(world, 14); Require(world.Tick == 32 && world.DoorHealthAt(3, 2) == 0 && world.ActorAt(2).targetId == 0, "Listener learned the hidden human before its next visual observation."); Run(world, 1); Require(world.ActorAt(2).x == 3 && world.ActorAt(2).targetId == 1 && world.ActorAt(2).lastSeenX == 2 && world.ActorAt(2).heardDoorUntilTick == 0, "Open sightline did not replace sound investigation with real pursuit."); Inspect(world); // Arrival clears the heard location while retaining the newly observed human target.
        }); // Finish event-to-sight acceptance.
        Check("Expired sound memory returns a blocked investigator to occasional wandering", () => // Hearing must not produce permanent camping or an endless search.
        { // Begin a saved recent impact with no humans in the world.
            WorldMap map = new WorldMap(10, 6); map.Set(3, 2, Terrain.DoorClosed); World world = new World(map, 4, encounter: true); int id; world.TrySpawn(Species.Zombie, 4, 2, out id); SaveDocument saved = world.Capture(); saved.actors[0].heardDoorX = 3; saved.actors[0].heardDoorY = 2; saved.actors[0].heardDoorUntilTick = 2; world = World.Restore(saved); world.Step(); Require(world.ActorAt(0).x == 4 && world.DoorHealthAt(3, 2) == 100, "Sound-only investigation attacked its closed source."); world.Step(); Require(world.ActorAt(0).heardDoorUntilTick == 0 && world.ActorAt(0).heardDoorX == 0 && world.ActorAt(0).heardDoorY == 0, "Sound memory did not expire between actor opportunities."); Run(world, 4); Require(world.ActorAt(0).x != 4 || world.ActorAt(0).y != 2, "Idle chance did not resume after investigation expired."); Require(world.DoorHealthAt(3, 2) == 100, "An expired sound justified a later attack."); Inspect(world); // Fixed seed four makes the first post-expiry idle opportunity move.
        }); // Finish expiry acceptance.
        Check("Visible humans and remembered sightings override a different sound source", () => // A nearby bang cannot distract a zombie from its actual pursuit.
        { // Begin visible-target priority.
            WorldMap map = new WorldMap(30, 20); map.Set(12, 8, Terrain.DoorClosed); World world = new World(map, 214, encounter: true); int id; world.TrySpawn(Species.Zombie, 10, 10, out id); world.TrySpawn(Species.Human, 6, 10, out id); SaveDocument saved = world.Capture(); saved.actors[0].heardDoorX = 12; saved.actors[0].heardDoorY = 8; saved.actors[0].heardDoorUntilTick = 25; world = World.Restore(saved); world.Step(); Require(world.ActorAt(0).x == 9 && world.ActorAt(0).y == 10 && world.ActorAt(0).targetId == 2 && world.DoorHealthAt(12, 8) == 100, "A sound displaced a visible human target."); // Pursue left while the sound lies to the right.
            saved = EncounterScenarios.ZombieWandering().Capture(); map = WorldMap.Restore(saved.map); map.Set(8, 5, Terrain.DoorClosed); saved.map = map.Capture(); saved.actors[1].heardDoorX = 8; saved.actors[1].heardDoorY = 5; saved.actors[1].heardDoorUntilTick = 25; world = World.Restore(saved); Run(world, 2); Require(world.ActorAt(1).targetId == 1 && world.ActorAt(1).x == 6 && world.DoorHealthAt(5, 5) == 84 && world.DoorHealthAt(8, 5) == 100, "Sound diverted an active remembered-door search."); // Preserve the previously observed doorway while another door is merely heard.
        }); // Finish priority acceptance.
        Check("Zombie listeners obey acoustic reach and cannot walk through a transmitting window", () => // Hearing and physical route reachability remain different queries.
        { // Begin bounded listeners.
            World world = EncounterScenarios.DoorBreach(); SaveDocument saved = world.Capture(); WorldMap map = WorldMap.Restore(saved.map); for (int y = 4; y <= 6; y++) for (int x = 7; x <= 9; x++) map.Set(x, y, Terrain.Wall); map.Set(8, 5, Terrain.Floor); saved.map = map.Capture(); world = World.Restore(saved); int id; world.TrySpawn(Species.Zombie, 7, 2, out id); world.TrySpawn(Species.Zombie, 10, 6, out id); world.TrySpawn(Species.Zombie, 8, 5, out id); Run(world, 2); Require(world.ActorAt(2).heardDoorUntilTick == 27 && world.ActorAt(3).heardDoorUntilTick == 0 && world.ActorAt(4).heardDoorUntilTick == 0, "Zombie hearing ignored range or enclosing walls."); // No additional human can distract the emitting attacker.
            map = new WorldMap(5, 1); map.Set(1, 0, Terrain.DoorOpen); map.Set(2, 0, Terrain.Window); world = new World(map, 214, encounter: true); world.TrySpawn(Species.Zombie, 3, 0, out id); saved = world.Capture(); saved.actors[0].heardDoorX = 1; saved.actors[0].heardDoorUntilTick = 25; world = World.Restore(saved); Run(world, 20); Require(world.ActorAt(0).x == 3 && world.ActorAt(0).targetId == 0 && world.TerrainAt(2, 0) == Terrain.Window && world.DoorConditionRevision == 0, "Investigating a sound crossed or attacked an impassable window."); Inspect(world); // A real acoustic path does not grant a walkable one.
        }); // Finish geometry acceptance.
        Check("Reaching an open sound source ends its investigation", () => // Clear an inspected location without inventing a human.
        { // Begin arrival cleanup.
            WorldMap map = new WorldMap(5, 1); map.Set(1, 0, Terrain.DoorOpen); World world = new World(map, 214, encounter: true); int id; world.TrySpawn(Species.Zombie, 3, 0, out id); SaveDocument saved = world.Capture(); saved.actors[0].heardDoorX = 1; saved.actors[0].heardDoorUntilTick = 25; world = World.Restore(saved); Run(world, 1); Require(world.ActorAt(0).x == 2 && world.ActorAt(0).heardDoorUntilTick == 25, "Investigation ended before reaching the source."); Run(world, 5); Require(world.ActorAt(0).x == 1 && world.ActorAt(0).heardDoorUntilTick == 0 && world.ActorAt(0).targetId == 0, "Arriving at an empty source left stale hearing or invented a target."); Require(State(world) == State(Documents.ParseSave(State(world))), "Arrived investigator failed save validation."); // Wandering becomes eligible on later opportunities.
        }); // Finish arrival acceptance.
        Check("Sound investigation pauses, resumes exactly and ignores hidden human movement", () => // Retain sound memory without reading the hidden target's position.
        { // Begin actual-event saved continuation.
            World world = EncounterScenarios.ZombieSoundInvestigation(); Run(world, 2); string before = State(world); TickClock clock = new TickClock(); clock.Advance(100, world.Step); Require(State(world) == before, "Paused investigation consumed movement or memory time."); World resumed = Documents.ParseSave(before); for (int i = 0; i < 80; i++) { world.Step(); resumed.Step(); Require(State(world) == State(resumed), "Sound investigation diverged after save/load."); } Inspect(world); // Continue through noise, breach, human sight and later expiry.
            world = EncounterScenarios.ZombieWandering(); int id; world.TrySpawn(Species.Zombie, 8, 5, out id); SaveDocument changed = world.Capture(); changed.actors[0].x = 2; changed.actors[0].y = 7; changed.actors[0].shelterX = 2; changed.actors[0].shelterY = 7; World elsewhere = World.Restore(changed); for (int i = 0; i < 100; i++) { world.Step(); elsewhere.Step(); Require(Documents.Encode(world.ActorAt(2)) == Documents.Encode(elsewhere.ActorAt(2)) && world.Capture().randomState == elsewhere.Capture().randomState, "Sound investigator tracked a hidden human instead of actual door impacts."); } // The door remains closed after the short remembered search; both hidden cells hear the same actual strikes.
        }); // Finish persistence and knowledge acceptance.
        Check("Zombie hearing rejects stale sources and pre-investigation rules", () => // Do not silently reinterpret old sensory records.
        { // Begin new-species saved validation.
            World world = EncounterScenarios.ZombieSoundInvestigation(); Run(world, 2); SaveDocument saved = world.Capture(); saved.rulesVersion = EncounterRules.HearingVersion; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[2].heardDoorX = 4; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[2].heardDoorUntilTick = saved.tick; Reject(() => World.Restore(saved)); saved = world.Capture(); saved.actors[2].heardDoorUntilTick = 0; Reject(() => World.Restore(saved)); Require(State(world) == State(Documents.ParseSave(State(world))), "Valid zombie hearing did not round-trip."); // The same door-source and deadline rules apply to both listener species in the current generation.
        }); // Finish state validation.
        Check("Prototype-eleven saves retain independent human-only hearing behavior", () => // Existing saves must explicitly opt into attracted zombies.
        { // Begin prior-release compatibility.
            string folder = Path.Combine(AppContext.BaseDirectory, "Fixtures"); World world = Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v11-input.json"))); Require(world.DoorHearing && !world.ZombieSoundInvestigation, "Previous hearing save silently enabled zombie investigation."); Run(world, 80); Require(State(world) == State(Documents.ParseSave(File.ReadAllText(Path.Combine(folder, "encounter-v11-expected.json")))), "Previous human hearing and zombie continuation changed."); // Reference was independently executed from commit 18248f7.
        }); // Finish compatibility acceptance.
    } // Finish zombie sound cases.
} // Finish runner integration.
